window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-26201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 622⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 622 na letra μ · nº geral 26201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">8 τοὺς δὲ καὶ μετεστήσαντο tuc. e os exilaram também</p></section></article>\n<article id=\"entry-dgp-26202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 623⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 623 na letra μ · nº geral 26202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">9 Αἰνείας ἑτάροισι μεθίστατο hom. Enéias colocou-se entre os companheiros</p></section></article>\n<article id=\"entry-dgp-26203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 624⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 624 na letra μ · nº geral 26203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">10 ἅτε εἰς ἀμείνω οἶκον μεταστησάμενος plat. já que se mudara para uma moradia melhor, μεθίστασθαι κατὰ μῆνας εἰς ἕτερον ἀεὶ τόπον plat. mudar todo mês para um lugar diferente, τοὺς πρότερόν τε μετισταμένους ἐκ τῆς τάξιος εἴδετε her. vistes os que antes abandonavam os postos, μεθίσταμαι κότου ésql. rejeito a mágoa,</p></section></article>\n<article id=\"entry-dgp-26204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 625⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 625 na letra μ · nº geral 26204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">11 οὐδὲ αὐτὸς μεθίσταται plat. nem ele próprio se altera.</p></section></article>\n<article id=\"entry-dgp-26205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθό</h1><div class=\"entry-meta\"><span>DGP · ordem 626 na letra μ · nº geral 26205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μεθ’ ὅ depois do que. 〈μετά, n. de ὅς〉</p></section></article>\n<article id=\"entry-dgp-26206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθοδεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 627 na letra μ · nº geral 26206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. fraude; artifício; truque. 〈μεθοδεύω〉</p></section></article>\n<article id=\"entry-dgp-26207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθοδεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 628 na letra μ · nº geral 26207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 procurar alcançar de maneira regular e metódica 2 praticar com método 3 tratar com método 4 comportar-se desonestamente com alguém, ac. ou ἐν e dat.; enganar; seduzir ♦ méd. 5 usar de ardil, de artifícios. 〈μέθοδος〉</p></section></article>\n<article id=\"entry-dgp-26208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθοδικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 629 na letra μ · nº geral 26208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que investiga com método; que age metodicamente; metódico; sistemático. 〈μέθοδος〉</p></section></article>\n<article id=\"entry-dgp-26209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέθοδος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 630 na letra μ · nº geral 26209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pesquisa metódica; pesquisa científica 2 plano metódico; método 3 teoria metódica; sistema científico 4 ciência 5 tratado metódico; obra científica 6 tard. desvio; fraude; ardil. 〈μετά, ὁδός〉</p></section></article>\n<article id=\"entry-dgp-26210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθολκή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 631 na letra μ · nº geral 26210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">diversão; distração. 〈μετά, ἕλκω〉</p></section></article>\n<article id=\"entry-dgp-26211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθομιλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 632 na letra μ · nº geral 26211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ép. μεθομίλεον) relacionar-se com; viver em meio de, dat.</p></section></article>\n<article id=\"entry-dgp-26212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθορία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 633 na letra μ · nº geral 26212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μεθόριος.</p></section></article>\n<article id=\"entry-dgp-26213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθόριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 634 na letra μ · nº geral 26213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem fronteira com; limítrofe ♦ ἡ με­θορία 2 o país vizinho; o país fronteira 3 meio-termo ♦ τὸ μεθόριον, τὰ μεθόρια 4 fronteira; limite. 〈μετά, ὅρος〉</p></section></article>\n<article id=\"entry-dgp-26214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθορμάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 635 na letra μ · nº geral 26214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. μεθορμήθην) perseguir; lançar-se sobre, ac. 〈μετά, ὁρμάω〉</p></section></article>\n<article id=\"entry-dgp-26215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθορμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 636 na letra μ · nº geral 26215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor. μεθορμῆσαι) = μεθορμίζω.</p></section></article>\n<article id=\"entry-dgp-26216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθορμίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 637 na letra μ · nº geral 26216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. át. μεθορμιῶ, aor. μεθώρμισα) 1 fazer mudar de ancoradouro 2 deslocar; transportar 3 intr. mudar de ancoradouro ♦ méd. 4 intr. mudar de ancoradouro 5 deslocar-se de; sair de. 〈μετά, ὁρμίζω〉</p></section></article>\n<article id=\"entry-dgp-26217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέθυ, υος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 638 na letra μ · nº geral 26217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só sing. bebida fermentada; vinho: μέθυ ἡδύ hom. vinho suave, ἐκ κριθῶν μέθυ ésql. vinho de cevada, i.e., cerveja.</p></section></article>\n<article id=\"entry-dgp-26218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθυμναῖος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 639 na letra μ · nº geral 26218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. o deus do vinho; o deus da embriaguez, epít. de Dioniso.</p></section></article>\n<article id=\"entry-dgp-26219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθύσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 640 na letra μ · nº geral 26219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μεθύσω, aor. ἐμέθυσα, perf. desus.; méd. só pres. e impf.; pas. fut. μεθυσθήσομαι, aor. ἐμεθύσθην, perf. μεμέθυσμαι) 1 embriagar 2 molhar; embeber; ensopar ♦ méd. pas. 3 embriagar-se de, dat. ou gen. 4 inebriar-se 5 festejar; fazer rega-bofe. 〈μέθυ〉</p></section></article>\n<article id=\"entry-dgp-26220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέθυσος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 641 na letra μ · nº geral 26220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bêbado; ébrio. 〈μέθυ〉</p></section></article>\n<article id=\"entry-dgp-26221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθύστερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 642 na letra μ · nº geral 26221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 posterior ♦ οἱ μεθύστεροι 2 os descendentes; a posteridade ♦ μεθύστερον adv. 3 posteriormente 4 mais tarde; no porvir ♦ τὸ μεθύστερον adv. 5 daqui em diante. 〈μετά, ὕστερον〉</p></section></article>\n<article id=\"entry-dgp-26222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεθύω</h1><div class=\"entry-meta\"><span>DGP · ordem 643 na letra μ · nº geral 26222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) 1 estar bêbado; estar embriagado de, gen. ou ὑπό e gen. 2 inebriar-se de, dat., gen. ou ὑπό e gen. 3 estar encharcado; estar inundado; estar impregnado de, gen. ou dat. 4 estar aturdido. 〈μέθυ〉</p></section></article>\n<article id=\"entry-dgp-26223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μεθωναῖος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 644 na letra μ · nº geral 26223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de Metona. 〈Μεθώνη〉</p></section></article>\n<article id=\"entry-dgp-26224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μεθώνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 645 na letra μ · nº geral 26224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Metona, porto da Messênia 2 Metona, n. de cidade da Argólida, da Magnésia e cidade da Trácia.</p></section></article>\n<article id=\"entry-dgp-26225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 646 na letra μ · nº geral 26225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μείξω, aor. ἔμειξα; aor. pas. ἐμίχθην e ἐμί­γην) = μίγνυμι.</p></section></article>\n<article id=\"entry-dgp-26226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειγνύω</h1><div class=\"entry-meta\"><span>DGP · ordem 647 na letra μ · nº geral 26226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μείγνυμι.</p></section></article>\n<article id=\"entry-dgp-26227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειδάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 648 na letra μ · nº geral 26227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor.1 poét. μείδησα) = μειδιάω.</p></section></article>\n<article id=\"entry-dgp-26228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειδίαμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 649 na letra μ · nº geral 26228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sorriso. 〈μειδιάω〉</p></section></article>\n<article id=\"entry-dgp-26229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειδιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 650 na letra μ · nº geral 26229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μειδιάσω, aor. ἐμειδίασα, perf. desus.) rir docemente; sorrir.</p></section></article>\n<article id=\"entry-dgp-26230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειδιόων, όωσα</h1><div class=\"entry-meta\"><span>DGP · ordem 651 na letra μ · nº geral 26230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. masc. e fem. ép. de μειδιάω.</p></section></article>\n<article id=\"entry-dgp-26231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεῖζον</h1><div class=\"entry-meta\"><span>DGP · ordem 652 na letra μ · nº geral 26231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. e ac. neutro, μείζοσι dat. pl. de μείζων.</p></section></article>\n<article id=\"entry-dgp-26232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειζότερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 653 na letra μ · nº geral 26232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl., comp. de μέγας.</p></section></article>\n<article id=\"entry-dgp-26233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειζόνως,</h1><div class=\"entry-meta\"><span>DGP · ordem 654 na letra μ · nº geral 26233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. μεζόνως adv. mais; mais grandemente. 〈μείζων〉</p></section></article>\n<article id=\"entry-dgp-26234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείζων,</h1><div class=\"entry-meta\"><span>DGP · ordem 655 na letra μ · nº geral 26234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. μέζων, ων, ον comp. de μέγας.</p></section></article>\n<article id=\"entry-dgp-26235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείλανι</h1><div class=\"entry-meta\"><span>DGP · ordem 656 na letra μ · nº geral 26235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. ép. de μέλας.</p></section></article>\n<article id=\"entry-dgp-26236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείλιγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 657 na letra μ · nº geral 26236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tempero de uma iguaria 2 o que suaviza; o que alivia; bálsamo; remédio para, gen. 3 sacrifício propiciatório 4 canto agradável às Musas 5 pl. palavras afetuosas. 〈μειλίσσω〉</p></section></article>\n<article id=\"entry-dgp-26237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειλικτήρια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 658 na letra μ · nº geral 26237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sacrifícios propiciatórios. 〈μειλίσσω〉</p></section></article>\n<article id=\"entry-dgp-26238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείλινος1, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 659 na letra μ · nº geral 26238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = μέλινος.</p></section></article>\n<article id=\"entry-dgp-26239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείλινος2, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 660 na letra μ · nº geral 26239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μείλιχος.</p></section></article>\n<article id=\"entry-dgp-26240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 661 na letra μ · nº geral 26240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. pl. 1 encantamento destinado a conjurar, gen. 2 oferenda de ação de graças; oferenda de agradecimento 3 presente de casamento 4 indenização. 〈μέλι〉</p></section></article>\n<article id=\"entry-dgp-26241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειλίσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 662 na letra μ · nº geral 26241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ίττω (fut. μειλίξω, aor. ἐμείλιξα, perf. desus.) 1 apaziguar; acalmar; aplacar com, dat. ou gen. 2 lisonjear; seduzir; ganhar alguém 3 tornar macio (o chão) ♦ méd. 4 dizer palavras gentis; tratar com cortesia, ac. 5 tornar propício para si, ac. 6 pedir; implorar.</p></section></article>\n<article id=\"entry-dgp-26242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειλίχια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 663 na letra μ · nº geral 26242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μειλίχιος.</p></section></article>\n<article id=\"entry-dgp-26243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειλιχίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 664 na letra μ · nº geral 26243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 doçura; afabilidade; delicadeza 2 benevolência 3 tibieza; frouxidão. 〈μειλίχιος〉</p></section></article>\n<article id=\"entry-dgp-26244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειλίχιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 665 na letra μ · nº geral 26244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 feito de mel; preparado com mel 2 doce como mel; agradável; encantador; delicioso: ἔπεσσι μειλιχίοισι ou só μειλιχίοισι hom. com amáveis palavras 3 que suaviza; que acalma; apaziguador; propício, epít. de divindades ♦ τὰ μειλίχια 4 sacrifícios propiciatórios ♦ μειλίχιον adv. 5 docemente. 〈μέλι〉</p></section></article>\n<article id=\"entry-dgp-26245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείλιχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 666 na letra μ · nº geral 26245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">doce; agradável; amável com alguém, dat. 〈μέλι〉</p></section></article>\n<article id=\"entry-dgp-26246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεῖναι, μεῖνον</h1><div class=\"entry-meta\"><span>DGP · ordem 667 na letra μ · nº geral 26246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. e imper. aor. de μένω.</p></section></article>\n<article id=\"entry-dgp-26247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεῖον1, ονος</h1><div class=\"entry-meta\"><span>DGP · ordem 668 na letra μ · nº geral 26247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">n. de μείων.</p></section></article>\n<article id=\"entry-dgp-26248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεῖον2, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 669 na letra μ · nº geral 26248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cordeiro ou ovelha que se oferecia para a entrada de uma criança em uma fratria.</p></section></article>\n<article id=\"entry-dgp-26249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειονεκτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 670 na letra μ · nº geral 26249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ter menos do que o necessário; ter muito pouco; ser pobre 2 ter falta de; estar sem; carecer de algo, gen. 3 ser inferior a alguém, gen. 〈μεῖον, ἑκτέος〉</p></section></article>\n<article id=\"entry-dgp-26250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειονεξία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 671 na letra μ · nº geral 26250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inferioridade.</p></section></article>\n<article id=\"entry-dgp-26251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 672 na letra μ · nº geral 26251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. menos; muito pouco. 〈μείων〉</p></section></article>\n<article id=\"entry-dgp-26252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείουρος, ος ον</h1><div class=\"entry-meta\"><span>DGP · ordem 673 na letra μ · nº geral 26252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de cauda muito curta 2 Arquit. cujo cume é menos largo que a base 3 Métr. miúro, verso hexâmetro datílico, cujo último pé é formado por um iambo ou um pírrico (em lugar de um espondeu ou um troqueu) 4 Ret. truncado (período). 〈μείων, οὐρά〉</p></section></article>\n<article id=\"entry-dgp-26253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 674 na letra μ · nº geral 26253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar menor; diminuir; reduzir, ac. 2 ser ou tornar-se inferior a, gen. 3 diminuir; apequenar; rebaixar 4 diminuir; moderar 5 Pros. abreviar uma sílaba. 〈μείων〉</p></section></article>\n<article id=\"entry-dgp-26254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειρακιεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 675 na letra μ · nº geral 26254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. ter um ardor juvenil; ferver de ardor; ser petulante. 〈μεῖραξ〉</p></section></article>\n<article id=\"entry-dgp-26255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειράκιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 676 na letra μ · nº geral 26255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jovem adolescente; rapazote, que deixou de ser παῖς e não é ainda ἀνήρ; ἐκ μειρακίου, ἐκ μειρακίων isócr. a partir da adolescência, ἐν μειρακίῳ d.c. na adolescência. 〈μεῖραξ〉</p></section></article>\n<article id=\"entry-dgp-26256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειρακιόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 677 na letra μ · nº geral 26256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tornar-se adolescente. 〈μεῖραξ〉</p></section></article>\n<article id=\"entry-dgp-26257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειρακίσκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 678 na letra μ · nº geral 26257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">menina moça; adolescente. 〈μεῖραξ〉</p></section></article>\n<article id=\"entry-dgp-26258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειρακίσκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 679 na letra μ · nº geral 26258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rapazote; adolescente. 〈μεῖραξ〉</p></section></article>\n<article id=\"entry-dgp-26259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειρακιώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 680 na letra μ · nº geral 26259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de um homem jovem; conveniente a um homem jovem 2 pueril; ingênuo ♦ τὸ μειρακιῶδες 3 puerilidade. 〈μειράκιον, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-26260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μειρακύλλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 681 na letra μ · nº geral 26260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">homem jovem; adolescente. 〈μεῖραξ〉</p></section></article>\n<article id=\"entry-dgp-26261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεῖραξ, ακος (ἡ,</h1><div class=\"entry-meta\"><span>DGP · ordem 682 na letra μ · nº geral 26261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">post. ὁ) 1 fem. menina moça 2 fem., tard. homem homossexual 3 masc., tard. rapazote.</p></section></article>\n<article id=\"entry-dgp-26262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείρομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 683 na letra μ · nº geral 26262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., perf. ἔμμορα; perf. pas. εἴμαρμαι, tard. μέμορμαι e μεμόρημαι, part. εἰμαρμένος, μεμορμένος e μεμορημένος) 1 receber em partilha, ac. 2 tard. dividir; repartir 3 perf. obter ou ter a parte que lhe cabe de, gen.: ἔμμορέ τοι τιμῆς, ὅς τ’ ἔμμορε γείτονος ἐσθλοῦ hes. obteve sua parte de honra aquele a quem coube um bom vizinho ♦ pas. perf. e m.-q.-perf. 4 impes. estar atribuído pela sorte, pelo destino; estar decidido pelo destino; ser destino fatal: τῷ τοιούτῳ εἵμαρται ἢ ἀπολωλέναι ὑπὸ τῶν ἐχθρῶν ἢ τυραννεῖν plat. para um tal [homem] é destino fatal ou morrer nas mãos dos inimigos ou tornar-se tirano, με λευγαλέῳ θανάτῳ εἵμαρτο ἁλῶναι hom. estava decidido pelo destino que eu fosse apanhado por uma triste morte 5 part. εἱμαρμένος, η, ον fixado pelo destino: χρόνος εἱμαρμένος γενέσεως plat. tempo destinado para o nascimento ♦ ἡ εἰμαρμένη e τὸ μεμορμένον 6 sorte fixada pelo destino; destino.</p></section></article>\n<article id=\"entry-dgp-26263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείς (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 684 na letra μ · nº geral 26263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = μήν2.</p></section></article>\n<article id=\"entry-dgp-26264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 685 na letra μ · nº geral 26264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">falta; carência; déficit. 〈μειόω〉</p></section></article>\n<article id=\"entry-dgp-26265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 686 na letra μ · nº geral 26265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος comp. de μικρός e ὀλίγος 1 menos grande; menor 2 inferior 3 menos numeroso ♦ μεῖον adv. 4 menos.</p></section></article>\n<article id=\"entry-dgp-26266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μείωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 687 na letra μ · nº geral 26266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 minoração; diminuição 2 minguante da lua. 〈μειόω〉</p></section></article>\n<article id=\"entry-dgp-26267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάγγαιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 688 na letra μ · nº geral 26267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de solo escuro; de solo fértil. 〈μέλας, γαῖα〉</p></section></article>\n<article id=\"entry-dgp-26268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάγκαρπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 689 na letra μ · nº geral 26268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de frutos negros. 〈μέλας, καρπός〉</p></section></article>\n<article id=\"entry-dgp-26269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάγκερως, ως, ων</h1><div class=\"entry-meta\"><span>DGP · ordem 690 na letra μ · nº geral 26269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de chifres negros. 〈μέλας, κέρας〉</p></section></article>\n<article id=\"entry-dgp-26270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάγκροκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 691 na letra μ · nº geral 26270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de tecidos negros. 〈μέλας, κρέκω〉</p></section></article>\n<article id=\"entry-dgp-26271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαγχαίτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 692 na letra μ · nº geral 26271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de cabeleira negra. 〈μέλας, χαίτη〉</p></section></article>\n<article id=\"entry-dgp-26272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάγχιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 693 na letra μ · nº geral 26272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 negro; sombrio ♦ τὰ μελάγχιμα 2 lugares sombrios. 〈μέλας, -χιμος〉</p></section></article>\n<article id=\"entry-dgp-26273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαγχίτων, ωνος</h1><div class=\"entry-meta\"><span>DGP · ordem 694 na letra μ · nº geral 26273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 vestido de negro; em traje de luto 2 triste; sombrio. 〈μέλας, χιτών〉</p></section></article>\n<article id=\"entry-dgp-26274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μελάγχλαινοι, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 695 na letra μ · nº geral 26274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">os Capas-pretas, tribo cita. 〈μέλας, χλαῖνα〉</p></section></article>\n<article id=\"entry-dgp-26275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαγχολάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 696 na letra μ · nº geral 26275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter a bile negra; ser triste. 〈μελάγχολος〉</p></section></article>\n<article id=\"entry-dgp-26276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαγχολία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 697 na letra μ · nº geral 26276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bile negra; melancolia. 〈μέλαγχολος〉</p></section></article>\n<article id=\"entry-dgp-26277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαγχολικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 698 na letra μ · nº geral 26277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de humor sombrio; de caráter melancólico 2 que pode gerar a melancolia. 〈μελαγχολία〉</p></section></article>\n<article id=\"entry-dgp-26278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάγχολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 699 na letra μ · nº geral 26278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">untado de bile negra. 〈μέλας, χολή〉</p></section></article>\n<article id=\"entry-dgp-26279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαγχροιής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 700 na letra μ · nº geral 26279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de cor negra ou escura 2 de pele negra. 〈μέλας, χρόα1〉</p></section></article>\n<article id=\"entry-dgp-26280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάγχροος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 701 na letra μ · nº geral 26280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μελαγχροιής.</p></section></article>\n<article id=\"entry-dgp-26281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάγχρως1, χροος</h1><div class=\"entry-meta\"><span>DGP · ordem 702 na letra μ · nº geral 26281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. pl. μελάγχροες = μελάγχρως2.</p></section></article>\n<article id=\"entry-dgp-26282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάγχρως2, ωτος</h1><div class=\"entry-meta\"><span>DGP · ordem 703 na letra μ · nº geral 26282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) = μελάγχροος. 〈μέλας, χρώς〉</p></section></article>\n<article id=\"entry-dgp-26283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέλαθρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 704 na letra μ · nº geral 26283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 viga do teto 2 teto; abóbada 3 ornamentos do teto 4 teto; casa; morada; residência.</p></section></article>\n<article id=\"entry-dgp-26284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαθρόφιν</h1><div class=\"entry-meta\"><span>DGP · ordem 705 na letra μ · nº geral 26284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. instr. ép. de μέλαθρον.</p></section></article>\n<article id=\"entry-dgp-26285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέλαινα</h1><div class=\"entry-meta\"><span>DGP · ordem 706 na letra μ · nº geral 26285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de μέλας.</p></section></article>\n<article id=\"entry-dgp-26286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαίνετο</h1><div class=\"entry-meta\"><span>DGP · ordem 707 na letra μ · nº geral 26286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. pas. poét. de μελαίνω.</p></section></article>\n<article id=\"entry-dgp-26287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 708 na letra μ · nº geral 26287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μελανῶ; pas. aor. ἐμελάνθην, perf. μεμέλασ­μαι) 1 tornar negro; enegrecer 2 tornar sombrio; tornar obscuro ♦ at. intr. e méd. 3 tornar-se negro; enegrecer-se. 〈μέλας〉</p></section></article>\n<article id=\"entry-dgp-26288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαμβαθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 709 na letra μ · nº geral 26288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">profundo em trevas; negro e profundo. 〈μέλας, βάθος〉</p></section></article>\n<article id=\"entry-dgp-26289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαμπαγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 710 na letra μ · nº geral 26289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que forma coágulos negros 2 negro. 〈μέλας, πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-26290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάμπεπλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 711 na letra μ · nº geral 26290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de peplo negro. 〈μέλας, πέπλος〉</p></section></article>\n<article id=\"entry-dgp-26291\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαμπῦγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 712 na letra μ · nº geral 26291</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de nádegas negras ou cobertas de pêlos negros, visto como indício de vigor. 〈μέλας, πυγή〉</p></section></article>\n<article id=\"entry-dgp-26292\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάμφυλλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 713 na letra μ · nº geral 26292</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de folhagem escura. 〈μέλας, φύλλον〉</p></section></article>\n<article id=\"entry-dgp-26293\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέλαν</h1><div class=\"entry-meta\"><span>DGP · ordem 714 na letra μ · nº geral 26293</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">n. de μέλας.</p></section></article>\n<article id=\"entry-dgp-26294\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάναιγις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 715 na letra μ · nº geral 26294</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 de égide negra, epít. de Dioniso e das Erínias 2 negro (vinho). 〈μέλας, αἰγίς〉</p></section></article>\n<article id=\"entry-dgp-26295\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελαναυγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 716 na letra μ · nº geral 26295</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">negro e luzidio; negro retinto. 〈μέλας, αὐγή〉</p></section></article>\n<article id=\"entry-dgp-26296\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελάνδετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 717 na letra μ · nº geral 26296</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de cadarços escuros ou de armação escura 2 enegrecido; negro. 〈μέλας, δέω1〉</p></section></article>\n<article id=\"entry-dgp-26297\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελανείμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 718 na letra μ · nº geral 26297</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 em negras vestes 2 que requer vestes escuras. 〈μέλας, εἷμα〉</p></section></article>\n<article id=\"entry-dgp-26298\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελανθέα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 719 na letra μ · nº geral 26298</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">capacidade de ver a cor preta.</p></section></article>\n<article id=\"entry-dgp-26299\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελανία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 720 na letra μ · nº geral 26299</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cor negra; negrura 2 mancha negra 3 nódoa; mácula (moral). 〈μέλας〉</p></section></article>\n<article id=\"entry-dgp-26300\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελανόζυξ, υγος</h1><div class=\"entry-meta\"><span>DGP · ordem 721 na letra μ · nº geral 26300</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de negros bancos de remeiros. 〈μέλας, ζυγόν〉</p></section></article>\n";
